<?php use App\Core\Csrf; ob_start(); $edit=!empty($user['id']); ?><div class="page-head"><div><h1><?=$edit?'Edit':'Create'?> User</h1></div><a href="/users">Back</a></div><div class="panel"><form method="post" action="<?=$edit?'/users/'.$user['id']:'/users'?>"><?=Csrf::field()?><div class="form-grid"><label>Name<input name="name" value="<?=e($user['name']??'')?>" required><?=isset($errors['name'])?'<small class="field-error">'.e($errors['name']).'</small>':''?></label><label>Email<input type="email" name="email" value="<?=e($user['email']??'')?>" required><?=isset($errors['email'])?'<small class="field-error">'.e($errors['email']).'</small>':''?></label><label>Password<input type="password" name="password" <?=$edit?'':'required'?> minlength="8" placeholder="<?=$edit?'Leave blank to keep current':''?>"><?=isset($errors['password'])?'<small class="field-error">'.e($errors['password']).'</small>':''?></label><label>Status<select name="status"><option value="active" <?=($user['status']??'active')==='active'?'selected':''?>>Active</option><option value="inactive" <?=($user['status']??'')==='inactive'?'selected':''?>>Inactive</option><option value="suspended" <?=($user['status']??'')==='suspended'?'selected':''?>>Suspended</option></select></label></div><fieldset><legend>Roles</legend><div class="checks"><?php $selected=[]; if(!empty($user['id'])){$found=explode(', ',(string)($user['roles']??''));}else{$found=[];} foreach($roles as $r): ?><label><input type="checkbox" name="roles[]" value="<?=$r['id']?>" <?=in_array($r['name'],$found,true)?'checked':''?>> <?=e($r['name'])?></label><?php endforeach; ?></div></fieldset><button class="primary" type="submit">Save user</button></form></div><?php $content=ob_get_clean();$title=$edit?'Edit User':'Create User';require dirname(__DIR__).'/layouts/app.php';
